proof fn suffix_suffix<T>(ex: Execution<T>, i: nat, j: nat)
    ensures ex.suffix(i).suffix(j) == ex.suffix(i + j)
{
    assert forall |k: nat| (ex.suffix(i).suffix(j).nat_to_state)(k) == (ex.suffix(i + j).nat_to_state)(k) by {
        assert((ex.suffix(i).suffix(j).nat_to_state)(k) == (ex.nat_to_state)(k + j + i));
        assert((ex.suffix(i + j).nat_to_state)(k) == (ex.nat_to_state)(k + (i + j)));
        assert(k + j + i == k + (i + j)) by (arithmetic);
    };
    execution_equality(ex.suffix(i).suffix(j), ex.suffix(i + j));
}

proof fn always_p_or_eventually_q<T>(ex: Execution<T>, next: TempPred<T>, p: TempPred<T>, q: TempPred<T>)
    requires
        always(p.and(next).implies(later(p).or(later(q)))).satisfied_by(ex),
        always(next).satisfied_by(ex),
    ensures always(p.implies(always(p).or(eventually(q)))).satisfied_by(ex),
{
    always_unfold(ex, p.and(next).implies(later(p).or(later(q))));
    always_unfold(ex, next);

    assert forall |i: nat| p.implies(always(p).or(eventually(q))).satisfied_by(#[trigger] ex.suffix(i)) by {
        let exi = ex.suffix(i);
        if p.satisfied_by(exi) {
            if !eventually(q).satisfied_by(exi) {
                // q never holds on any suffix of exi
                not_eventually_unfold(exi, q);

                // next always holds on exi
                always_propagate_forwards(ex, next, i);
                always_unfold(exi, next);

                // the implication holds at every suffix of exi
                always_propagate_forwards(ex, p.and(next).implies(later(p).or(later(q))), i);
                always_unfold(exi, p.and(next).implies(later(p).or(later(q))));

                // prove the transition condition for exi required by always_p_or_eventually_q_rec
                assert forall |idx: nat|
                    p.satisfied_by(#[trigger] exi.suffix(idx)) && next.satisfied_by(exi.suffix(idx)) ==>
                    p.satisfied_by(exi.suffix(idx + 1)) || q.satisfied_by(exi.suffix(idx + 1)) by {
                    if p.satisfied_by(exi.suffix(idx)) && next.satisfied_by(exi.suffix(idx)) {
                        implies_apply(exi.suffix(idx), p.and(next), later(p).or(later(q)));
                        // (later(p).or(later(q))).satisfied_by(exi.suffix(idx))
                        // = p(exi.suffix(idx).suffix(1)) || q(exi.suffix(idx).suffix(1))
                        // and exi.suffix(idx).suffix(1) == exi.suffix(idx + 1)
                        suffix_suffix(exi, idx, 1);
                    }
                };

                // p holds at every position of exi
                assert forall |j: nat| p.satisfied_by(#[trigger] exi.suffix(j)) by {
                    always_p_or_eventually_q_rec(exi, next, p, q, j);
                };

                assert always(p).satisfied_by(exi);
            }
            assert (always(p).or(eventually(q))).satisfied_by(exi);
        }
    };
}

